document.addEventListener("DOMContentLoaded",()=>{const e=[{label:"Height",value:"6,001 m",detail:"Deo Tibba is listed in the issue as a 6,001 metre peak."},{label:"State",value:"Himachal Pradesh",detail:"The mountain is associated with Himachal Pradesh's high Himalayan trekking landscape."},{label:"Range",value:"Pir Panjal",detail:"The issue identifies Deo Tibba with the Pir Panjal range."},{label:"Known for",value:"Trekking views",detail:"The region is known for alpine meadows, snow views, moraines, and dramatic Himalayan scenery."},{label:"Nearest hub",value:"Manali region",detail:"Deo Tibba treks are commonly planned from the Kullu-Manali side of Himachal Pradesh."},{label:"Page focus",value:"Nature + trek guide",detail:"The page combines natural beauty, quick facts, trekking information, gallery, and safety notes."}],a=[{title:"Trail character",text:"The Deo Tibba trekking region is known for forests, meadows, river crossings, moraine zones, and open Himalayan views."},{title:"Fitness level",text:"Trekkers should be comfortable with multi-day walking, altitude gain, cold weather, and uneven terrain."},{title:"Best planning window",text:"Season depends on snow and local conditions; travellers should check current advisories and local operator guidance."},{title:"Responsible trekking",text:"Follow Leave No Trace habits, avoid littering, respect local communities, and stay on safe marked routes."}],n=e=>String(e).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");document.getElementById("facts-grid").innerHTML=e.map(e=>`\n    <article class="fact-card">\n      <span>${n(e.label)}</span>\n      <strong>${n(e.value)}</strong>\n      <p>${n(e.detail)}</p>\n    </article>\n  `).join(""),document.getElementById("trek-grid").innerHTML=a.map((e,a)=>`\n    <article class="trek-card">\n      <span>0${a+1}</span>\n      <h3>${n(e.title)}</h3>\n      <p>${n(e.text)}</p>\n    </article>\n  `).join(""),document.getElementById("gallery-grid").innerHTML=[{title:"Alpine meadow",image:"../../assets/travel_mountains.png",caption:"Meadows and high Himalayan scenery around the Deo Tibba trekking landscape."},{title:"Forest approach",image:"../../assets/travel_hidden.png",caption:"Lower route sections often pass through forests and valley trails."},{title:"Snow view",image:"../../assets/hero_banner.png",caption:"Clear weather can reveal dramatic snow peaks and ridgelines."},{title:"Mountain camp",image:"../../assets/travel_mountains.png",caption:"Camp planning, weather checks, and acclimatisation awareness matter."}].map(e=>`\n    <article class="gallery-card">\n      <img src="${n(e.image)}" alt="${n(e.title)}" onerror="this.src='../../assets/hero_banner.png'">\n      <div>\n        <h3>${n(e.title)}</h3>\n        <p>${n(e.caption)}</p>\n      </div>\n    </article>\n  `).join(""),window.DeoTibbaMountainPage={facts:()=>[...e],trek:()=>[...a]}});